import java.nio.ByteBuffer;

public class Ipv4Checksum {
    static byte[] header(int total, int id, int flagsFrag, int ttl, int proto, int src, int dst) {
        ByteBuffer b = ByteBuffer.allocate(20);
        b.put((byte) 0x45).put((byte) 0).putShort((short) total).putShort((short) id);
        b.putShort((short) flagsFrag).put((byte) ttl).put((byte) proto);
        b.putShort((short) 0).putInt(src).putInt(dst);
        return b.array();
    }

    static int checksum(byte[] h) {
        long sum = 0;
        for (int i = 0; i < h.length; i += 2) {
            sum += ((h[i] & 0xFF) << 8) | (h[i + 1] & 0xFF);
        }
        while ((sum >> 16) != 0) {
            sum = (sum & 0xFFFF) + (sum >> 16);
        }
        return (int) (~sum & 0xFFFF);
    }

    static int ip(int a, int b, int c, int d) {
        return (a << 24) | (b << 16) | (c << 8) | d;
    }

    public static void main(String[] args) {
        byte[] h = header(60, 0x1c46, 0x4000, 64, 6, ip(192, 168, 1, 10), ip(203, 0, 113, 25));
        int cs = checksum(h);
        System.out.printf("checksum field = 0x%04x%n", cs);
        h[10] = (byte) (cs >> 8);
        h[11] = (byte) cs;
        StringBuilder sb = new StringBuilder();
        for (byte x : h) {
            sb.append(String.format("%02x ", x));
        }
        System.out.println(sb.toString().trim());
        System.out.printf("verification over full header = 0x%04x%n", checksum(h));
        h[8] = 63; // router decrements TTL; checksum is now stale
        System.out.printf("after TTL change, verification = 0x%04x (non-zero: corrupt)%n",
                checksum(h));
        int cs2 = checksum(header(60, 0x1c46, 0x4000, 63, 6, ip(192, 168, 1, 10),
                ip(203, 0, 113, 25)));
        System.out.printf("recomputed checksum with TTL 63 = 0x%04x%n", cs2);
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;

public class WhoAmI {
    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/who", ex -> {
            String peer = ex.getRemoteAddress().getAddress().getHostAddress();
            String xff = ex.getRequestHeaders().getFirst("X-Forwarded-For");
            String body = "peer=" + peer + " X-Forwarded-For=" + xff + "\n";
            byte[] out = body.getBytes(StandardCharsets.UTF_8);
            ex.sendResponseHeaders(200, out.length);
            ex.getResponseBody().write(out);
            ex.close();
        });
        server.start();
        int port = server.getAddress().getPort();
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest req = HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + port + "/who"))
                .header("X-Forwarded-For", "203.0.113.50, 10.0.0.7").build();
        System.out.print(client.send(req, HttpResponse.BodyHandlers.ofString()).body());
        server.stop(0);
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class SubnetCalc {
    static long parse(String s) {
        String[] p = s.split("\\.");
        long v = 0;
        for (String o : p) {
            v = (v << 8) | Integer.parseInt(o);
        }
        return v;
    }

    static String fmt(long v) {
        return ((v >> 24) & 255) + "." + ((v >> 16) & 255) + "."
                + ((v >> 8) & 255) + "." + (v & 255);
    }

    static String bin(long v) {
        String s = String.format("%32s", Long.toBinaryString(v)).replace(' ', '0');
        return s.substring(0, 8) + "." + s.substring(8, 16) + "." + s.substring(16, 24)
                + "." + s.substring(24);
    }

    static long mask(int prefix) {
        return prefix == 0 ? 0 : (0xFFFFFFFFL << (32 - prefix)) & 0xFFFFFFFFL;
    }

    static void describe(String cidr) {
        String[] p = cidr.split("/");
        long addr = parse(p[0]);
        int len = Integer.parseInt(p[1]);
        long m = mask(len);
        long net = addr & m;
        long bcast = net | (~m & 0xFFFFFFFFL);
        long total = 1L << (32 - len);
        long usable = len >= 31 ? total : total - 2;
        System.out.println("Address      : " + fmt(addr) + "  " + bin(addr));
        System.out.println("Mask         : " + fmt(m) + "  " + bin(m));
        System.out.println("Network      : " + fmt(net) + "/" + len);
        System.out.println("Broadcast    : " + fmt(bcast));
        System.out.println("Host range   : " + fmt(len >= 31 ? net : net + 1) + " - "
                + fmt(len >= 31 ? bcast : bcast - 1));
        System.out.println("Usable hosts : " + usable);
        System.out.println();
    }

    record Need(String name, int hosts) { }

    static void vlsm(String base, List<Need> needs) {
        long cursor = parse(base.split("/")[0]);
        List<Need> sorted = new ArrayList<>(needs);
        sorted.sort(Comparator.comparingInt(Need::hosts).reversed());
        System.out.printf("%-8s %6s %7s %-18s %-15s %s%n", "Name", "Hosts", "Prefix", "Network",
                "Broadcast", "Usable range");
        for (Need n : sorted) {
            int bits = 2;
            while ((1L << bits) - 2 < n.hosts()) {
                bits++;
            }
            int prefix = 32 - bits;
            long size = 1L << bits;
            long bcast = cursor + size - 1;
            System.out.printf("%-8s %6d %7s %-18s %-15s %s - %s%n", n.name(), n.hosts(),
                    "/" + prefix, fmt(cursor) + "/" + prefix, fmt(bcast), fmt(cursor + 1),
                    fmt(bcast - 1));
            cursor += size;
        }
    }

    public static void main(String[] args) {
        describe("192.168.10.77/26");
        describe("172.16.5.130/20");
        vlsm("192.168.50.0/24", List.of(new Need("LAN-A", 100), new Need("LAN-B", 50),
                new Need("LAN-C", 25), new Need("LAN-D", 10), new Need("WAN-1", 2),
                new Need("WAN-2", 2)));
    }
}

