import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.List;

public class RouteLookup {
    record Route(String cidr, String nextHop, String iface) {
        long network() { return toLong(cidr.split("/")[0]); }
        int length() { return Integer.parseInt(cidr.split("/")[1]); }
        boolean matches(long dst) {
            long mask = length() == 0 ? 0 : (0xFFFFFFFFL << (32 - length())) & 0xFFFFFFFFL;
            return (dst & mask) == network();
        }
    }

    static long toLong(String ip) {
        try {
            byte[] b = InetAddress.getByName(ip).getAddress();
            return ((b[0] & 0xFFL) << 24) | ((b[1] & 0xFF) << 16) | ((b[2] & 0xFF) << 8)
                    | (b[3] & 0xFF);
        } catch (UnknownHostException e) {
            throw new IllegalArgumentException(e);
        }
    }

    public static void main(String[] args) {
        List<Route> table = List.of(
                new Route("0.0.0.0/0", "10.0.0.1", "eth0"),
                new Route("10.1.0.0/16", "10.0.0.2", "eth0"),
                new Route("10.1.2.0/24", "10.0.0.3", "eth0"),
                new Route("10.1.2.128/25", "10.0.0.4", "eth0"),
                new Route("192.168.1.0/24", "direct", "eth1"));
        String[] targets = {"10.1.2.200", "10.1.2.77", "10.1.9.9", "192.168.1.50", "8.8.8.8"};
        for (String dst : targets) {
            long d = toLong(dst);
            Route best = null;
            StringBuilder matched = new StringBuilder();
            for (Route r : table) {
                if (r.matches(d)) {
                    matched.append(r.cidr()).append(' ');
                    if (best == null || r.length() > best.length()) {
                        best = r;
                    }
                }
            }
            System.out.printf("%-12s [%s]%n   -> %s via %s (%s)%n", dst, matched.toString().trim(),
                    best.cidr(), best.nextHop(), best.iface());
        }
    }
}

import java.util.LinkedHashMap;
import java.util.Map;

public class PatSim {
    record Endpoint(String ip, int port) {
        @Override
        public String toString() {
            return ip + ":" + port;
        }
    }

    static final String PUBLIC_IP = "203.0.113.7";
    static final Map<Endpoint, Integer> outbound = new LinkedHashMap<>();
    static final Map<Integer, Endpoint> inbound = new LinkedHashMap<>();
    static int nextPort = 40001;

    static Endpoint translateOut(Endpoint inside, Endpoint server) {
        int pub = outbound.computeIfAbsent(inside, k -> {
            int p = nextPort++;
            inbound.put(p, k);
            return p;
        });
        System.out.printf("OUT  %s > %s  =>  %s:%d > %s%n", inside, server, PUBLIC_IP, pub, server);
        return new Endpoint(PUBLIC_IP, pub);
    }
    static void translateIn(Endpoint server, int publicPort) {
        Endpoint inside = inbound.get(publicPort);
        if (inside == null) {
            System.out.printf("IN   %s > %s:%d  =>  dropped (no mapping)%n", server, PUBLIC_IP,
                    publicPort);
        } else {
            System.out.printf("IN   %s > %s:%d  =>  %s > %s%n", server, PUBLIC_IP, publicPort,
                    server, inside);
        }
    }

    public static void main(String[] args) {
        Endpoint server = new Endpoint("198.51.100.20", 443);
        Endpoint p = new Endpoint("192.168.1.10", 51000);
        Endpoint q = new Endpoint("192.168.1.11", 51000);
        translateOut(p, server);
        translateOut(q, server);
        translateOut(p, server);
        translateIn(server, 40002);
        translateIn(server, 40001);
        translateIn(server, 40009);
        System.out.println("Table: " + outbound);
    }
}

import java.nio.ByteBuffer;

public class DhcpDiscover {
    static String hex(byte[] b, int from, int to) {
        StringBuilder sb = new StringBuilder();
        for (int i = from; i < to; i++) {
            sb.append(String.format("%02x", b[i]));
            if (i < to - 1) {
                sb.append(' ');
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        byte[] mac = {0x02, 0x00, 0x00, (byte) 0xaa, (byte) 0xbb, (byte) 0xcc};
        ByteBuffer b = ByteBuffer.allocate(300);
        b.put((byte) 1).put((byte) 1).put((byte) 6).put((byte) 0);   // op, htype, hlen, hops
        b.putInt(0x3903f326);                                       // xid
        b.putShort((short) 0).putShort((short) 0x8000);             // secs, flags (broadcast)
        b.put(new byte[16]);                                        // ciaddr yiaddr siaddr giaddr
        b.put(mac).put(new byte[10]);                               // chaddr (16 bytes)
        b.put(new byte[64 + 128]);                                  // sname, file
        b.putInt(0x63825363);                                       // magic cookie
        b.put((byte) 53).put((byte) 1).put((byte) 1);               // option 53: DHCPDISCOVER
        b.put((byte) 55).put((byte) 3).put((byte) 1).put((byte) 3).put((byte) 6); // parameter list
        b.put((byte) 255);                                          // end
        byte[] msg = new byte[b.position()];
        b.flip();
        b.get(msg);
        System.out.println("BOOTP/DHCP payload length: " + msg.length + " bytes");
        System.out.println("op htype hlen hops : " + hex(msg, 0, 4));
        System.out.println("xid                : " + hex(msg, 4, 8));
        System.out.println("secs flags         : " + hex(msg, 8, 12));
        System.out.println("chaddr             : " + hex(msg, 28, 34));
        System.out.println("magic cookie       : " + hex(msg, 236, 240));
        System.out.println("options            : " + hex(msg, 240, msg.length));
        System.out.println("UDP/IP total       : " + (msg.length + 8 + 20) + " bytes");
    }
}

import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.NetworkInterface;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Collections;

public class BindDemo {
    static InetAddress firstExternalIpv4() throws Exception {
        for (NetworkInterface ni : Collections.list(NetworkInterface.getNetworkInterfaces())) {
            if (ni.isUp() && !ni.isLoopback()) {
                for (InetAddress a : Collections.list(ni.getInetAddresses())) {
                    if (a.getAddress().length == 4) {
                        return a;
                    }
                }
            }
        }
        throw new IllegalStateException("no external IPv4 address");
    }

    static void tryConnect(String label, ServerSocket server, InetAddress target) {
        try (Socket s = new Socket()) {
            s.connect(new InetSocketAddress(target, server.getLocalPort()), 1000);
            System.out.printf("%-22s connect to %s: OK%n", label, target.getHostAddress());
        } catch (Exception e) {
            System.out.printf("%-22s connect to %s: %s%n", label, target.getHostAddress(),
                    e.getClass().getSimpleName() + " (" + e.getMessage() + ")");
        }
    }

    public static void main(String[] args) throws Exception {
        InetAddress external = firstExternalIpv4();
        InetAddress loopback = InetAddress.getByName("127.0.0.1");
        try (ServerSocket loopbackOnly = new ServerSocket(0, 50, loopback);
             ServerSocket wildcard = new ServerSocket(0)) {
            System.out.println("loopback-only bound to " + loopbackOnly.getInetAddress());
            System.out.println("wildcard bound to      " + wildcard.getInetAddress()
                    + " (any-local=" + wildcard.getInetAddress().isAnyLocalAddress() + ")");
            tryConnect("server on 127.0.0.1", loopbackOnly, external);
            tryConnect("server on 0.0.0.0", wildcard, external);
        }
    }
}
